def semver_sort(versions):
    def parse(v):
        core = v
        pre = None
        if '+' in core:
            core = core.split('+', 1)[0]
        if '-' in core:
            idx = core.index('-')
            pre = core[idx+1:]
            core = core[:idx]
        major, minor, patch = (int(x) for x in core.split('.'))
        return (major, minor, patch, pre)

    def pre_key(pre):
        if pre is None:
            return None
        ids = pre.split('.')
        key = []
        for ident in ids:
            if ident.isdigit():
                key.append((0, int(ident), ''))
            else:
                key.append((1, 0, ident))
        return key

    def cmp_pre(pre1, pre2):
        if pre1 is None and pre2 is None:
            return 0
        if pre1 is None:
            return 1
        if pre2 is None:
            return -1
        k1 = pre_key(pre1)
        k2 = pre_key(pre2)
        for a, b in zip(k1, k2):
            if a < b:
                return -1
            elif a > b:
                return 1
        if len(k1) < len(k2):
            return -1
        elif len(k1) > len(k2):
            return 1
        return 0

    import functools

    def cmp(v1, v2):
        p1 = parse(v1)
        p2 = parse(v2)
        if p1[0] != p2[0]:
            return p1[0] - p2[0]
        if p1[1] != p2[1]:
            return p1[1] - p2[1]
        if p1[2] != p2[2]:
            return p1[2] - p2[2]
        return cmp_pre(p1[3], p2[3])

    return sorted(versions, key=functools.cmp_to_key(cmp))

